using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        PlayerMovement pm = GameObject.FindFirstObjectByType<PlayerMovement>();
        Vector3 spawnPos = pm != null ? pm.transform.position + pm.transform.forward * 2f + Vector3.up * 0.5f : Vector3.zero;

        GameObject sphere = GameObject.CreatePrimitive(PrimitiveType.Sphere);
        result.RegisterObjectCreation(sphere);
        sphere.name = "TimeReductionItem";
        sphere.transform.position = spawnPos;
        sphere.transform.localScale = Vector3.one * 0.5f;

        TimeReductionItem item = sphere.AddComponent<TimeReductionItem>();

        EditorSceneManager.MarkSceneDirty(sphere.scene);

        result.Log("Created TimeReductionItem at {0}", spawnPos);
    }
}

